import os
CSS='''*{box-sizing:border-box}body{margin:0;background:#f1f3f6;color:#172b47;font:15px system-ui,-apple-system,Arial}header{background:white;border-bottom:1px solid #ddd;padding:20px 7%;display:flex;justify-content:space-between;align-items:center}.logo{color:#FF5B00;font-weight:850;font-size:28px}.bar{background:#1E3A5F;color:#fff;padding:12px 7%;border-top:4px solid #FF5B00;font-size:13px}.content{max-width:960px;margin:28px auto;padding:0 24px}.card{background:white;border:1px solid #e1e5eb;border-radius:14px;padding:30px;box-shadow:0 2px 8px #152c4410}h1{font-size:29px;line-height:1.25;margin:8px 0 14px}h2{font-size:22px;margin:8px 0 12px}p{line-height:1.6;color:#546478}.mut{color:#66758a;font-size:13px}.step{display:flex;justify-content:space-between;gap:8px;background:#f8fafc;border:1px solid #e2e8f0;padding:17px;border-radius:10px;margin:22px 0}.done{color:#07835b;font-weight:700}.now{color:#FF5B00;font-weight:750}.btn{padding:13px 21px;background:white;border:1px solid #cbd5e1;border-radius:9px;font-weight:650;display:inline-block;color:#34465d;font-size:15px;text-align:center}.primary{background:#FF5B00;border-color:#FF5B00;color:white}.actions{display:flex;gap:12px;margin-top:24px}.cta{display:block;width:100%;font-size:18px;padding:17px}.tag{display:inline-block;background:#eaf7f1;color:#047857;border-radius:99px;padding:7px 13px;font-size:13px;font-weight:700}.notice{background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;border-radius:10px;padding:16px;line-height:1.5}.note{background:#fffbe8;border:1px dashed #e4b74c;padding:14px;border-radius:9px;margin:18px 0;font-size:13px;line-height:1.5;color:#765518}.stamp{position:fixed;bottom:12px;right:12px;padding:7px 12px;background:#fff3cd;border:1px solid #e4b74c;border-radius:7px;color:#854d0e;font-size:12px;font-weight:750}.veil{background:#152c446e;padding:60px 24px;border-radius:14px}.modal{max-width:550px;margin:auto;background:white;padding:32px;border-radius:16px;box-shadow:0 15px 50px #0003}.native{font:14px Arial;color:#202124;max-width:520px;margin:0 auto;background:white;padding:24px;border-radius:8px;box-shadow:0 10px 30px #0003}.native .btn{border-radius:4px;padding:9px 18px;font-size:13px}.blue{background:#1a73e8;color:#fff;border-color:#1a73e8}.row{display:flex;justify-content:space-between;gap:12px;align-items:center}.receipt{border:1px solid #e2e8f0;padding:16px;border-radius:9px;margin-top:22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.mailhead{border-bottom:1px solid #ddd;padding-bottom:14px;margin-bottom:20px;font-size:13px;line-height:1.8}.sms{background:#e9edf2;padding:20px;border-radius:20px;line-height:1.6;margin:18px 0;color:#233348}.link{color:#246c9a;overflow-wrap:anywhere}.foot{margin-top:22px;text-align:center;color:#66758a;font-size:12px}.mobile header{padding:15px}.mobile .logo{font-size:23px}.mobile .bar{padding:10px 15px}.mobile .content{margin:18px auto;padding:0 14px}.mobile .card{padding:22px}.mobile h1{font-size:25px}.mobile h2{font-size:21px}.mobile .step{font-size:13px;padding:13px;gap:4px}.mobile .veil{padding:24px 10px}.mobile .modal{padding:23px}.mobile .actions{flex-direction:column}.mobile .grid{grid-template-columns:1fr}.mobile .stamp{font-size:10px;right:8px;bottom:8px}.mobile .native{padding:20px}.mobile .native .actions{flex-direction:row;justify-content:flex-end}.mobile .native .btn{padding:9px}.mobile .row{flex-wrap:wrap}.mobile .cta{font-size:16px}.mobile .content .mailhead{font-size:12px}'''
def app(b,m=False):
 return '<body class="%s"><header><span class="logo">UNIACC</span><span class="mut">%s</span></header><div class="bar">Camila Ejemplo Rojas · Psicología · Rematrícula 2027-1</div><main class="content">%s<div class="foot">Sitio Rematrícula Online · UNIACC</div></main><div class="stamp">DATOS FICTICIOS · PROPUESTA / NO IMPLEMENTADO</div></body>'%('mobile' if m else '', '☰ &nbsp; Salir' if m else 'Rematrícula 2027-1 &nbsp;&nbsp; Salir',b)
STEP='<div class="step"><span class="done">✓ Matrícula</span><span>→</span><span class="now">2 Arancel</span><span>→</span><span class="mut">3 Firma</span></div>'
BEFORE='''<div class="note"><b>1 · Cerrar pestaña / recargar</b><br>Diálogo ilustrativo del navegador. Texto y botones NO personalizables. Puede no mostrarse, especialmente en móvil; requiere interacción previa.</div><div class="veil"><div class="native"><b>¿Salir del sitio?</b><p style="color:#3c4043">Es posible que los cambios que has realizado no se guarden.</p><div class="actions" style="justify-content:flex-end"><span class="btn">Cancelar</span><span class="btn blue">Salir</span></div></div></div><div class="note">No dice “tu matrícula está pagada”: el navegador decide el mensaje. No guarda datos ni envía avisos. Durante el envío autorizado a Webpay/TuFirma se desarma temporalmente.</div>'''
MODAL='''<div class="note"><b>2 · Salir, logo, menú o Atrás dentro de MOL</b><br>Confirmación propia del router. No intercepta por sí sola cerrar la pestaña ni todas las salidas externas.</div><div class="veil"><div class="modal"><span style="font-size:32px;color:#FF5B00">◷</span><h2>Te falta completar tu rematrícula</h2><p>Tu matrícula está pagada, pero tu rematrícula no está completa. Falta elegir cómo pagarás el arancel y firmar tu contrato.</p><div class="notice">Tu pago ya fue recibido. No necesitas volver a pagar la matrícula.</div><div class="actions"><span class="btn primary">Completar ahora</span><span class="btn">Salir igual</span></div></div></div><div class="note">“Salir igual” respeta la salida elegida y conserva el borrador. Si el arancel ya está resuelto: cambiar el texto a “Falta firmar tu contrato”. Nunca bloquear el avance normal.</div>'''
RETURN='''<div class="card"><span class="tag">✓ Webpay autorizado</span><h1>Pago de matrícula recibido<br><span style="color:#FF5B00">Paso 1 de 3</span></h1><p>¡Gracias, Camila! Ya recibimos tu pago de matrícula. Ahora elige cómo pagarás tu arancel y firma el contrato para completar tu rematrícula.</p>'''+STEP+'''<div class="notice"><b>Tu rematrícula aún no está completa.</b><br>No vuelvas a pagar la matrícula: continúa con los pasos pendientes.</div><div class="actions"><span class="btn primary cta">Continuar con el arancel →</span></div><div class="mut" style="text-align:center;margin-top:12px">Puedes elegir Webpay o pagaré, según las opciones disponibles.</div><div class="receipt"><div class="row"><b>Comprobante de matrícula</b><span class="link">Ver detalle ▾</span></div><div class="row mut" style="margin-top:10px"><span>$200.000 · 05/11/2026 15:40 (Santiago)</span><span>Descargar comprobante</span></div></div></div><div class="note">La acción principal deja de ser “Descargar voucher”. Respetar siguientePaso(): si el arancel está cubierto o resuelto, CTA “Continuar a la firma”. Si la persistencia falla: “Tu pago está recibido; reintenta guardar el avance”, sin repetir el cobro.</div>'''
REENTRY='''<div class="notice"><b>Tu matrícula ya está pagada. Retomemos donde quedaste.</b><p style="color:#9a3412;margin:8px 0">Falta elegir el medio del arancel y firmar tu contrato. No necesitas volver a pagar la matrícula.</p><span class="btn primary">Retomar mi rematrícula →</span><div class="mut" style="margin-top:10px">Te estamos llevando al paso pendiente…</div></div><div class="card" style="margin-top:18px"><span class="tag">Avance recuperado de forma segura</span><h1>Completa tu arancel</h1>'''+STEP+'''<p>Tu pago de matrícula está confirmado. Elige una alternativa para el arancel y luego firma tu contrato.</p><div class="grid"><div class="receipt"><b>Webpay</b><p>Paga el arancel en línea.</p><span class="btn primary">Elegir Webpay</span></div><div class="receipt"><b>Pagaré</b><p>Revisa las cuotas disponibles.</p><span class="btn">Elegir pagaré</span></div></div></div><div class="note">Después del login: esperar carga y conciliación de borrador + Webpay + contrato. router.replace al paso pendiente, sin bucle ni nuevo cobro. Si no se puede verificar, ofrecer reintentar; no asumir matrícula impaga.</div>'''
def email(stage):
 is24=stage==24
 title='Tu rematrícula sigue pendiente' if is24 else 'Tu matrícula ya está pagada. Completa tu rematrícula'
 return '''<div class="card"><span class="tag">%s h · Correo · transporte existente / automatización nueva</span><div class="mailhead" style="margin-top:18px"><b>Para:</b> camila.ejemplo@example.com<br><b>De:</b> Universidad UNIACC · remitente institucional por validar<br><b>Asunto:</b> %s</div><span class="logo">UNIACC</span><h2>%s</h2><p>Hola, Camila:</p><p>%s</p><div class="notice">Tu pago de matrícula ya fue recibido. No necesitas volver a pagarlo.</div><p>Falta elegir cómo pagarás el arancel y firmar tu contrato para completar tu rematrícula 2027-1.</p><span class="btn primary cta">Retomar mi rematrícula →</span><p class="mut">Si ya avanzaste, al ingresar verás el paso que corresponda. Necesitas iniciar sesión. Nunca te pediremos claves por correo.</p><div class="receipt mut">Enlace de ejemplo (ruta por crear):<br><span class="link">https://mol.example.com/retomar</span></div></div>'''%(stage,title,title,'Ha pasado un día desde tu pago y todavía quedan pasos pendientes. Te invitamos a completar tu proceso.' if is24 else 'Recibimos tu pago de matrícula hace dos horas. Estás a un paso de retomar tu proceso.')
def sms(stage):
 return '''<div class="card"><span class="tag">%s h · SMS Celmedia</span><h2>Recordatorio breve</h2><p class="mut">Integración existente para OTP. Plantilla y disparador de retención nuevos. WhatsApp: no encontrado; requeriría canal nuevo.</p><div class="sms">UNIACC: tu matricula ya esta pagada. %s Retoma tu rematricula: <span class="link">https://mol.example.com/retomar</span></div><div class="note">Enlace ilustrativo, no operativo. Dominio UNIACC a definir. SMS puede usar varios segmentos por longitud. No incluir RUT, datos de tarjeta ni enlaces de firma con acceso directo.</div></div>'''%(stage,'Falta arancel y firma.' if stage==2 else 'Aun falta completar arancel y firma.')
P={}
for key,body in [('01-beforeunload',BEFORE),('02-modal-salida',MODAL),('03-retorno-webpay',RETURN),('05-reingreso',REENTRY)]:
 for device,w,h in [('escritorio',1280,1020),('movil',430,1260)]: P[key+'-'+device]=(w,h,app(body,device=='movil'))
for hr in [2,24]:
 P['04-correo-%sh'%hr]=(850,1120,app(email(hr)))
 P['04-sms-%sh-movil'%hr]=(430,960,app(sms(hr),True))
for key,(w,h,b) in P.items():
 path=os.path.abspath('html/'+key+'.html');open(path,'w').write('<!doctype html><html><meta charset="utf-8"><style>'+CSS+'</style>'+b+'</html>')
 code=os.system('google-chrome --headless=new --no-sandbox --disable-gpu --hide-scrollbars --window-size=%d,%d --screenshot=%s.png file://%s 2>/dev/null'%(w,h,key,path))
 assert code==0
print('Generados',len(P),'PNG')
